func stockoutSignalBadgeClass(s domain.StockoutSignal) string {
	switch s {
	case domain.SignalStockout:
		return "border-rose-400/60 bg-rose-500/25 text-rose-100"
	case domain.SignalThinSupply:
		return "border-amber-400/55 bg-amber-500/20 text-amber-100"
	default:
		return "border-violet-400/50 bg-violet-500/20 text-violet-100"
	}
}

